            "tag": "Cấu trúc",
            "body": "\"Cái quan trọng nhất là niềm tin vào việc tăng giá bất động sản không còn nữa, và chiến lược đầu cơ bất động sản đang dần dần thay đổi. Với nền lãi suất rất cao cũng như giá trị bất động sản đang dần trở lại mức giá trị thực, những doanh nghiệp phát triển phân khúc như ngày xưa — biệt thự phân lô, khu đô thị chưa phát triển đồng bộ, chỉ mua bán để đầu cơ với nhau — sẽ khá rủi ro trong dài hạn.\" DXG, DIG, PDR, CII, TCH đều gần đáy hơn gần đỉnh, nhưng nếu mua thì mua ít và phải có điểm cắt lỗ."
