            "tag": "Nợ",
            "body": "\"Ở Việt Nam để mà vỡ nợ và phá sản thì khó lắm. Còn nói về vỡ nợ thì nợ nó không trả được mấy năm qua thì trên một góc độ nào đó thì là vỡ nợ rồi.\" Vấn đề gốc: nhiều dự án nghỉ dưỡng ở khu biệt lập \"không có sinh khí, không có đời sống thường nhật\", và pháp lý chưa đầy đủ nên không triển khai được. Chi phí huy động vốn thực tế của doanh nghiệp BĐS lên tới 15%/năm — lãi kép 5 năm là gấp đôi, mà giá 5 năm có tăng gấp đôi được không?"
